mapper.update:
update credit_account
set balance = balance - #{amount},
    total_consumed = total_consumed + #{amount},
    update_time = now()
where user_id = #{userId}
  and balance >= #{amount}

update credit_account
set balance = balance - #{amount},
    total_expired = total_expired + #{amount},
    update_time = now()
where user_id = #{userId}
  and balance >= #{amount}

mapper.select:
select id, user_id, balance, frozen, total_granted, total_consumed, total_expired, create_time, update_time
from credit_account
where user_id = #{userId}

mapper.update:
update credit_batch
set remaining = remaining - #{amount},
    update_time = now()
where id = #{id}
  and user_id = #{userId}
  and remaining >= #{amount}

update credit_batch
set state = 'exhausted', update_time = now()
where id = #{id}
  and user_id = #{userId}
  and remaining = 0

update credit_batch
set state = 'expired', update_time = now()
where id = #{id}
  and user_id = #{userId}
  and state = 'active'

mapper.select:
select id, user_id, event_id, scene, amount, remaining, granted_at, expires_at, state
from credit_batch
where state = 'active'
  and expires_at <= #{now}
order by expires_at asc
limit #{limit}

select id, user_id, biz_no, batch_id, scene, type, delta, balance_after, create_time
from credit_ledger
where user_id = #{userId}
order by id desc
limit #{limit}

select coalesce(sum(remaining), 0)
from credit_batch
where user_id = #{userId}
  and state = 'active'
  and remaining > 0
  and expires_at > #{now}

select coalesce(sum(delta), 0)
from credit_ledger
where user_id = #{userId}

select coalesce(sum(remaining), 0)
from credit_batch
where user_id = #{userId}
  and state = 'active'
  and remaining > 0
  and expires_at >= #{from}
  and expires_at < #{to}
